#!/usr/bin/env python3
"""Patch the android/ and ios/ folders generated by `flutter create` so that
Nectar Mobile gets: internet + notification permissions, core-library
desugaring (required by flutter_local_notifications), iOS background modes
and the WorkManager task identifier, plus the iOS AppDelegate wiring.

Idempotent: safe to run repeatedly. Every step reports what it did and warns
(instead of aborting) when a file does not look like it expects, so you can
apply that step manually - see README.md.

Usage: patch_platforms.py <project_dir>
"""
import plistlib
import re
import sys
from pathlib import Path


def log(msg):
    print(f"  - {msg}")


def warn(msg):
    print(f"  ! {msg}", file=sys.stderr)


def task_id(root: Path) -> str:
    cfg = (root / "lib/src/config.dart").read_text()
    m = re.search(r"kTaskId\s*=\s*'([^']+)'", cfg)
    if not m:
        raise SystemExit("could not find kTaskId in lib/src/config.dart")
    return m.group(1)


# --------------------------------------------------------------------------- android


def patch_manifest(root: Path):
    p = root / "android/app/src/main/AndroidManifest.xml"
    if not p.exists():
        return warn("AndroidManifest.xml not found")
    s = p.read_text()
    orig = s

    for perm in ("android.permission.INTERNET", "android.permission.POST_NOTIFICATIONS"):
        if perm not in s:
            s = s.replace("<application", f'<uses-permission android:name="{perm}"/>\n    <application', 1)
            log(f"manifest: added {perm}")

    if "usesCleartextTraffic" not in s:
        # lets you use a plain http://host:8081 admin URL (e.g. on a LAN)
        s = s.replace("<application", '<application\n        android:usesCleartextTraffic="true"', 1)
        log("manifest: allowed cleartext (http://) connections")

    s = re.sub(r'android:label="[^"]*"', 'android:label="Nectar"', s, count=1)

    if s != orig:
        p.write_text(s)
    else:
        log("manifest: already patched")


def patch_gradle(root: Path):
    app = root / "android/app"
    for name, kts in (("build.gradle.kts", True), ("build.gradle", False)):
        p = app / name
        if p.exists():
            break
    else:
        return warn("android/app/build.gradle(.kts) not found")

    s = p.read_text()
    if "coreLibraryDesugaring" in s:
        return log("gradle: desugaring already configured")
    if "compileOptions {" not in s:
        return warn(f"{p.name}: no compileOptions block - add desugaring manually (see README)")

    if kts:
        flag = "isCoreLibraryDesugaringEnabled = true"
        dep = '\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n}\n'
    else:
        flag = "coreLibraryDesugaringEnabled true"
        dep = "\ndependencies {\n    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.4'\n}\n"

    s = s.replace("compileOptions {", "compileOptions {\n        " + flag, 1)
    s = s.rstrip("\n") + "\n" + dep
    p.write_text(s)
    log(f"gradle: enabled core library desugaring in {p.name}")


# --------------------------------------------------------------------------- iOS


def patch_plist(root: Path, tid: str):
    p = root / "ios/Runner/Info.plist"
    if not p.exists():
        return warn("ios/Runner/Info.plist not found")
    with p.open("rb") as f:
        d = plistlib.load(f)
    before = plistlib.dumps(d)

    modes = d.setdefault("UIBackgroundModes", [])
    if "fetch" not in modes:
        modes.append("fetch")
    ids = d.setdefault("BGTaskSchedulerPermittedIdentifiers", [])
    if tid not in ids:
        ids.append(tid)
    # allow plain http:// admin URLs (the login screen warns about it)
    d.setdefault("NSAppTransportSecurity", {"NSAllowsArbitraryLoads": True})
    d["CFBundleDisplayName"] = "Nectar"

    if plistlib.dumps(d) != before:
        with p.open("wb") as f:
            plistlib.dump(d, f)
        log("Info.plist: background modes + task identifier + display name")
    else:
        log("Info.plist: already patched")


def patch_ios_target(root: Path):
    podfile = root / "ios/Podfile"
    if podfile.exists():
        s = podfile.read_text()
        new = re.sub(r"^\s*#?\s*platform :ios, '[^']*'", "platform :ios, '14.0'", s, count=1, flags=re.M)
        if new != s:
            podfile.write_text(new)
            log("Podfile: platform ios 14.0")
    pbx = root / "ios/Runner.xcodeproj/project.pbxproj"
    if pbx.exists():
        s = pbx.read_text()

        def bump(m):
            return m.group(0) if float(m.group(1)) >= 14.0 else "IPHONEOS_DEPLOYMENT_TARGET = 14.0;"

        new = re.sub(r"IPHONEOS_DEPLOYMENT_TARGET = ([0-9.]+);", bump, s)
        if new != s:
            pbx.write_text(new)
            log("project.pbxproj: deployment target 14.0")


APP_DELEGATE_IMPLICIT = """import Flutter
import UIKit
import UserNotifications
import workmanager_apple

@main
@objc class AppDelegate: FlutterAppDelegate, FlutterImplicitEngineDelegate {
  override func application(
    _ application: UIApplication,
    didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?
  ) -> Bool {
    WorkmanagerPlugin.registerLaunchHandlers()
    WorkmanagerPlugin.setPluginRegistrantCallback { registry in
      GeneratedPluginRegistrant.register(with: registry)
    }
    UNUserNotificationCenter.current().delegate = self as? UNUserNotificationCenterDelegate
    return super.application(application, didFinishLaunchingWithOptions: launchOptions)
  }

  func didInitializeImplicitFlutterEngine(_ engineBridge: FlutterImplicitEngineBridge) {
    GeneratedPluginRegistrant.register(with: engineBridge.pluginRegistry)
  }
}
"""

APP_DELEGATE_CLASSIC = """import Flutter
import UIKit
import UserNotifications
import workmanager_apple

@main
@objc class AppDelegate: FlutterAppDelegate {
  override func application(
    _ application: UIApplication,
    didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?
  ) -> Bool {
    GeneratedPluginRegistrant.register(with: self)
    WorkmanagerPlugin.setPluginRegistrantCallback { registry in
      GeneratedPluginRegistrant.register(with: registry)
    }
    UNUserNotificationCenter.current().delegate = self as? UNUserNotificationCenterDelegate
    return super.application(application, didFinishLaunchingWithOptions: launchOptions)
  }
}
"""


def patch_app_delegate(root: Path):
    p = root / "ios/Runner/AppDelegate.swift"
    if not p.exists():
        return warn("AppDelegate.swift not found")
    s = p.read_text()
    if "workmanager_apple" in s:
        return log("AppDelegate.swift: already wired")
    # `flutter create` templates differ by Flutter version (UIScene lifecycle)
    new = APP_DELEGATE_IMPLICIT if "FlutterImplicitEngineDelegate" in s else APP_DELEGATE_CLASSIC
    p.write_text(new)
    kind = "UIScene/implicit-engine" if new is APP_DELEGATE_IMPLICIT else "classic"
    log(f"AppDelegate.swift: rewritten for workmanager + notifications ({kind} template)")


def main():
    if len(sys.argv) != 2:
        raise SystemExit(__doc__)
    root = Path(sys.argv[1]).resolve()
    tid = task_id(root)
    print("Patching Android:")
    patch_manifest(root)
    patch_gradle(root)
    print("Patching iOS:")
    patch_plist(root, tid)
    patch_ios_target(root)
    patch_app_delegate(root)


if __name__ == "__main__":
    main()
